WordHunterWoW_QuestDataByFlavor = WordHunterWoW_QuestDataByFlavor or {}
WordHunterWoW_QuestDataByFlavor.classic = WordHunterWoW_QuestDataByFlavor.classic or {}
WordHunterWoW_QuestDataByFlavor.classic.enUS = WordHunterWoW_QuestDataByFlavor.classic.enUS or {}
local quests = WordHunterWoW_QuestDataByFlavor.classic.enUS
quests[1978] = { title = "The Deathstalkers", description = "The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.\n\nLord Varimathras will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.\n\nAh, and how could I forget?\n\nWelcome to the Deathstalkers.", objectives = "Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1998] = { title = "Fenwick Thatros", description = "Lord Varimathras has just sent me a missive about a threat to the Forsaken that must be immediately removed. His name is Fenwick Thatros, one whom Lord Varimathras believes is a leader of the undead that have taken root in Silverpine Forest.\n\nYour name came to mind immediately, $n. I have faith enough in your abilities that you will carry out this mission flawlessly.\n\nThe latest reports from the Deathstalkers in Silverpine indicate that Thatros can be found near the decrepit dock on Lordamere.", objectives = "Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[1999] = { title = "Tools of the Trade", description = "The wizards of the Kirin Tor at Ambermill have stored away important documents pertaining to the current state of Dalaran. This we know from the admissions of one of our prisoners. Lord Varimathras has placed the duty of recovering them in the hands of the Deathstalkers.\n\nThis task falls to you, $n. You will need some equipment, however, and the knowledge of lockpicking. Speak with Estelle Gendry, our outfitter, and ask her for a set of tools before you set out.", objectives = "Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2038] = { title = "Bingles' Missing Supplies", description = "As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives. With no gyrocopter and no explosives, the movement has no chance!\n\nGet my tools back and find my Blastencapper explosives, $N. For Gnomeregan! ", objectives = "Find and return Bingles' supplies:\n\nBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2039] = { title = "Find Bingles", description = "We've lost contact with Bingles! He was sent on a reconnaissance mission over Gnomeregan and hasn't reported back in over a week. I just know he's gone and blown himself up.\n\nHe was last seen flying over the Loch. Perhaps you can investigate, $N.", objectives = "Find Bingles Blastenheimer in Loch Modan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2040] = { title = "Underground Assault", description = "Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help, $N.\n\nDeep in the Deadmines is a functional goblin shredder. Find that shredder and bring back the intact power supply. With the shredder's power supply, we can give our gyrodrillmatic excavationators the power they need to break through the rocky underground borders of Gnomeregan, opening the way for a gnomish assault!", objectives = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2041] = { title = "Speak with Shoni", description = "Perhaps... Perhaps you can help us in the battle for Gnomeregan.\n\nIn Stormwind you will find the commander of our underground assault crew, Shoni the Shilent. Shoni needs assistance with her gyrodrillmatic excavationators.\n\nYou will probably find her amongst the dwarves in Stormwind.\n\nGood luck, $N. ", objectives = "Speak with Shoni the Shilent in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2078] = { title = "Gyromast's Revenge", description = "Landlubber, ye needs to find me first mate.\n\nTake this'n key, puts it in his gulliver an' bring him back here to serve the Cap'n.\n\nThem murlocs an' their chief ain't gonna be too happy once me first mate gets a hold of em!", objectives = "Find Gelkak's First Mate, the Threshwackonator 4100, and lead it back to Gelkak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2098] = { title = "Gyromast's Retrieval", description = "A pirate's life ain't an easy one, landlubber. It ain't all about plunderin' and booze! Alas, me ship be sunk just off shore thanks to them pesky Threshadons.\n\nWhat I be needin' is me first mate back in workin' order!\n\nWhen I washed up'n shore, the key for me first mate broke on the rocks and was pilfered by the beasties of Darkshore. Out of the corner of me eyes I saw some of them Ragin' Crawlers, Ferocious Foreststrider, and murloc rummaging through the wreckage....", objectives = "Find and return the three pieces of Gelkak's Key to Gelkak Gyromast.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2118] = { title = "Plagued Lands", description = "A sickness spreads across the Darkshore, gripping the minds and bodies of all it touches.\n\nThe Thistle Bears have been hit the hardest by this plague. The once noble beasts are now an instrument of destruction - rabid and frenzied. I may have a cure for this ailment.\n\nTake this trap to the forest and lay it on the ground. Any Rabid Thistle Bear that crosses the light shall become docile for a short time. Once the bear is docile, it shall follow you. Lead it back here, $N.", objectives = "Capture a living Rabid Thistle Bear and bring it back to Tharnariun.\n\nShould you fail to capture a Rabid Thistle Bear and lose your trap, return to Tharnariun Treetender and request another trap.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2138] = { title = "Cleansing of the Infected", description = "As I had feared, the cure does not work.\n\nIt saddens me greatly to order the death of any of nature's beasts, but the sick and tainted thistle bears must be put down.\n\nReturn to the forest and destroy 20 rabid thistle bears, $N. It will most certainly not put a stop to the plague but it will slow down the damage the animals are doing to our forest and its inhabitants for a short time.", objectives = "Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2139] = { title = "Tharnariun's Hope", description = "The survival of our people and lands comes at unfortunate costs, $N.\n\nYou have spilled the blood of nature's servants; many sick animals you have felled. The people of Auberdine are indebted to you, for the forest's pain is eased - even if only for a moment.\n\nI have one final task for you, but be warned, you will have to kill again. It is my hope that this will be the last time I call upon you, $N.\n\nIn a cave to the northeast, near Bashal'Aran, resides the Den Mother. Slay her.", objectives = "Find and kill the Den Mother.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2158] = { title = "Rest and Relaxation", description = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!\n\nMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.\n\nTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!", objectives = "Speak with Innkeeper Farley at the Lion's Pride Inn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2159] = { title = "Dolanaar Delivery", description = "Greetings, young $c.  Can you offer me aid?  I have a package of herbs that I must deliver to the town of Dolanaar.  But I still have business with the druids of Shadowglen and cannot yet leave.\n\nCan you deliver this package for me?  It must be sent to Innkeeper Keldamyr, at the Dolanaar inn.  It lies along the road, to the south.", objectives = "Bring the Dolanaar Delivery to Innkeeper Keldamyr.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2160] = { title = "Supplies to Tannok", description = "Hey! You look like a hearty adventurer. If you're planning on braving the pass, do you suppose you could bring a package to the inn in Kharanos?\n\nYou were planning on stopping at the inn, right? If you make it through the pass, you'll definitely want to take a breather there.\n\nAnyways, bring this to Tannok Frosthammer, the innkeeper's assistant. I can't get through the pass myself, and it'll be days until a Mountaineer escort comes through!", objectives = "Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2161] = { title = "A Peon's Burden", description = "Excuse me?  Can you help me?\n\nI have a load of food here.  I walked along the road and braved scorpids and spiders and worse!  I brought the food to the Valley of Trials because I thought they needed it and I like to help out.  But they don't need any food!  Now I have to take it back to Razor Hill and I'm afraid of all the beasts along the way...\n\nCan you take it for me?  I'm just a peon, but you're a hero.  You fear nothing!\n\nTake it to Innkeeper Grosk at the Razor Hill inn.  Thank you!", objectives = "Bring Ukor's Burden to Innkeeper Grosk in Razor Hill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2178] = { title = "Easy Strider Living", description = "Do you smell that delicious aroma? It's my secret recipe, $N--fresh strider stew. Delicious!\n\nPerhaps you would be interested in learning the recipe?\n\nBefore I teach you the recipe, you will need to prove that you can handle the beasts.\n\nNow, I don't expect you to go out and tame one and ride it back to me, but if you can kill a few and bring back some of their succulent meat, I may be persuaded to show you the ways of strider stew.", objectives = "Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2198] = { title = "The Shattered Necklace", description = "You have found a tarnished necklace, though the tarnish belies intricate and magical craftsmanship.  The necklace has been shattered, as its setting appears to be missing three gems.  On the underside of the necklace is the faint imprint of the city seal for Ironforge.  Below the seal are three tiny, engraved letters: \"TdK\".\n\nIf there is anything to be gleaned from the necklace, you will need to learn about its origins.  Perhaps the seal and the initials are a start...", objectives = "Search for the original creator of the shattered necklace to learn of its potential value.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2199] = { title = "Lore for a Price", description = "I am a jeweler of great renown here in Ironforge!  Well, former renown anyway... I have fallen onto hard times due to the chicanery of a competitor!  A bad reputation in this business spells financial disaster.  As a result, I find myself without a copper to my good-though-currently-sullied name.\n\nI want you to get me five silver bars to finish an order I received - the first in what seems like an eternity.\n\nYou get me those five silver bars, and I'll answer your questions on the necklace.", objectives = "Bring five silver bars to Talvash del Kissel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2200] = { title = "Back to Uldaman", description = "A competitor of mine started a rumor that my necklace cursed the paladin.  Needless to say, no one wants to buy cursed items from a jeweler.\n\n$N, I'll make you a deal - find the gems and I'll reassemble the necklace, so long as you'll advertise that I do NOT make cursed items!\n\nTry looking for clues in Uldaman; maybe see if the paladin's body is down there, since he's the one who we know had it last!  When you find the gems you should use this; it'll allow you to contact me here in Ironforge.", objectives = "Search for clues as to the current disposition of Talvash's necklace within Uldaman.  The slain paladin he mentioned was the person who has it last.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2201] = { title = "Find the Gems", description = "The paladin's journal has provided perhaps the only clues that Uldaman will yield as to the location of the necklace's gems.  If the paladin's scribing remains accurate, then the Shadowforge dwarves and the troggs that vie for control of the dig site will need to be dealt with.\n\nArmed with this knowledge, the search for the gems begins in earnest.  When all the gems have been acquired, Talvash in Ironforge should be notified via the Phial of Scrying as per his instructions.", objectives = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n\n* The sapphire has been claimed by Grimlok, the trogg leader.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2202] = { title = "Uldaman Reagent Run", description = "I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters, deep in the Uldaman dig site; they may be elsewhere, but for now that's the only place I know they're at.  I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!", objectives = "Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2203] = { title = "Badlands Reagent Run II", description = "You have been most helpful to me, $c.  I would reward you with the very recipe for the brew I gave you earlier... but I would ask of you a task that is quite dangerous.  Hear my request.\n\nThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be warned.  Once you have all three filled, bring them to me.\n\nDo this, and the recipe will be yours.", objectives = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Jarkal Mossmeld in Kargath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2204] = { title = "Restoring the Necklace", description = "You are going to need to find some \"oomph\" for the necklace, and Uldaman is probably the best place for it, actually.  I guess there are a lot of constructs running around in there, yeah?  Well, take out the biggest, baddest construct in that place and grab its power source!  I am pretty sure I can fuse that source into the necklace.\n\nWithout that power source, fixing the necklace will be impossible.  Come back to me here to Ironforge when you have it, and we'll get it all fixed up for you!", objectives = "Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2205] = { title = "Seek out SI: 7", description = "The badge? Oh, it's nothing, fish - nothing you could handle anyhow. By the looks of you, I'd say Mathias is likely to mistake you for the cheese delivery $g boy:girl; instead of a proper rogue. Regardless, I've been assigned a job and I've made a promise to deliver on that job.\n\nSpeaking of which, deliver this package to Mathias and he may give you a small task or two.\n\nGet cracking. ", objectives = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2206] = { title = "Snatch and Grab", description = "Our operatives in the field are reporting heavy Defias activity south of Goldshire. The reports indicate that the Defias have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall.\n\nI need you to infiltrate the dock house and get me that shipping schedule, $N. You will probably find it buried deep in the pockets of the Dockmaster.\n\n...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence.", objectives = "Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2218] = { title = "Road to Salvation", description = "Another lost soul looking for guidance, eh? I suppose you want to find a purpose - your purpose. I've seen it a thousand times, another hero looking for work.\n\nWell, today's your lucky day, friend. Hogral's got the cure for your ailment.\n\nHere's what you do: Take this road here up to Ironforge and make your way to the Forlorn Cavern. Once there, locate the thieves' guild and speak with Hulfdan Blackbeard. He'll put you on the road to salvation.", objectives = "Speak with Hulfdan Blackbeard in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2238] = { title = "Simple Subterfugin'", description = "Ye see, the King be strip mining the quarry fer ore and gems. More riches than any one dwarf should see in ten lifetimes.\n\nThe Hidden Circle has values, $N. We value valuables. Can ye understand?\n\nNow we feels the King should be sharing some of that booty, but we don't want ol' 'Stinkbeard' to know he's sharin' - if ye catch me drift.\n\nWe needs ye to speak with Onin MacHammar over by Gnomeregan and bring back a report. The crafty dwarf has hidden hisself amongst the lepers. Be careful.", objectives = "Find Onin MacHammar by Gnomeregan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2239] = { title = "Onin's Report", description = "The Quarry? Yap, I see those monstrous armored steam tanks come by this post near every day.\n\nMy contacts to the east tell me that the tank starts off at Ironforge, makes a pickup at the Gol'Bolar Quarry, stops over at Kharanos to refuel and then for some blasted reason, it takes the long way around past Gnomeregan, before reaching Ironforge to drop off the shipment.\n\nIt's all in the report, $r. Take it back to Hulfdan so he can plan the next step.", objectives = "Take Onin's Report back to Hulfdan in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2240] = { title = "The Hidden Chamber", description = "Now for the task at hand.\n\nThere is a secret chamber, the Chamber of Khaz'mul, that must be explored.  The problem is that the chamber's behind a huge, locked door!  It's a lucky thing I know how to open it.\n\nI've described everything in my journal, here on the table.  My band and I are stuck here for now... so you, $N, must find the chamber of Khaz'mul for us!\n\nRead my journal, explore the chamber, then report to Prospector Stormpike at the Explorers' League in Ironforge.", objectives = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2241] = { title = "The Apple Falls", description = "They say I'm 'lovestruck,' whatever that means.\n\nSure, I spend my every waking moment thinking about Syurna. Sure, my home is full of paintings and drawings of Syurna. Sure, I often go days without eating, sleeping, or drinking, while I lament about the love we could have had. Is that so wrong?\n\nNow she won't see me! ME! I've tried sending her messages but she won't even talk to another person unless they are a rogue.\n\nCould you deliver this flower to her? Don't forget to tell her it's from Jannok.", objectives = "Take Jannok's Rose to Syurna in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2242] = { title = "Destiny Calls", description = "We believe there is one being that may be able to help us understand what is happening to the forests of Teldrassil. Unfortunately, getting the creature to cooperate has proven disastrous.\n\nHe hides on a branch at the outskirts of the Oracle Glade. All who have so far approached the satyr, whether through force or diplomacy, have met with doom. Perhaps stealth is the answer, $N.\n\nFind what Sethir the Ancient carries in his packs and report back to me.", objectives = "Find Sethir the Ancient and bring back any clues that you may discover to Syurna.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2258] = { title = "Badlands Reagent Run", description = "$N, I could use your aid if you're up for it.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.  Watcha wanna do?", objectives = "Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2259] = { title = "Erion Shadewhisper", description = "Do not worry, $N, I am not sending you to see Syurna. Erion requires your presence at the Cenarion Enclave. Make haste!", objectives = "Contact Erion Shadewhisper in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2260] = { title = "Erion's Behest", description = "Word of your deeds has spread far and wide, $N. So far, in fact, that Stormwind Intelligence has asked for you by name.\n\nThe journey is taxing and not without peril, but an opportunity to train under SI:7 should not be taken lightly.\n\nA new world awaits you, $N. Make your way to Old Town in Stormwind and speak with Renzik \"The Shiv\" at SI:7 headquarters.", objectives = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\"", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2278] = { title = "The Platinum Discs", description = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.\n\n\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"\n\nYou have uncovered a wealth of previously undiscovered worldly lore!", objectives = "Speak with stone watcher and learn what ancient lore it keeps.  Once you have learned what lore it has to offer, activate the Discs of Norgannon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2279] = { title = "The Platinum Discs", description = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The Explorers' League in Ironforge is such a group, known throughout the Alliance; perhaps they can make good use of it.", objectives = "Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2280] = { title = "The Platinum Discs", description = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The sages of Thunder Bluff are such historians, known throughout the Horde; perhaps they can make good use of it.", objectives = "Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2281] = { title = "Redridge Rendezvous", description = "Sending you out in the field now would be suicide. Renzik doesn't need another dead rogue on his hands. Don't fret, though, $N - Renzik is going to get you up to speed.\n\nMake your way to the Redridge Mountains and speak with an associate of SI:7 named Lucius. You will find him hanging around the docks of Lakeshire with the other shady good-for-nothings.", objectives = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2282] = { title = "Alther's Mill", description = "We've been training thieves here for years! After all, not every rapscallion is born with the grace and finesse of old Lucius.\n\nUp off the road here you'll find Alther's Mill. I got a chest up there with something important inside. Go get it for me! Bring back that token and you'll receive your Certificate of Thievery!", objectives = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2283] = { title = "Necklace Recovery", description = "We've got work for you, that is if you've got the guts to do it!\n\nDeep in the Badlands is the Uldaman dig site.  We've heard a tale about some idiot paladin who died there recently.  Why we even care is that he had a very valuable necklace on him.  It's supposedly got three large gems: a ruby, a sapphire, and a topaz.\n\nThe shot: we want it, and we're payin' TOP SILVER to get it.  It may be damaged, but that's neither here nor there; we'll fix whatever scratches are on it.", objectives = "Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar.  The necklace may be damaged.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2284] = { title = "Necklace Recovery, Take 2", description = "As sure as Malton is a dummy, those gems are still in Uldaman somewhere.  You're going to have to go back there and look for them.\n\nLike I said before, if the information we have is correct then there's a ruby, a sapphire, and a topaz that go with the necklace.  Find them and put them in the necklace.\n\nAs to where the gems are, who knows?  Maybe you'll get lucky and find the corpse of the Paladin.  If he's not been stripped clean already, then maybe he's got them on him still.", objectives = "Find a clue as to the gems' whereabouts in the depths of Uldaman.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2298] = { title = "Kingly Shakedown", description = "So there we were, about to start plottin' out phase III when a couple o' Magni's blockheads come bargin' in here talkin' bout some kind o' heist and arresting some o' the Hidden Circle.\n\nWell nobody puts the iron on old Blackbeard! The argumentations got heavy and thick and somehow yer name weres blurted out!\n\nMe advice? Take the first Gryphon out o' Ironforge and get to Stormwind. Get yerself to Old Town and once there, talk to an old friend o' mine named Renzik \"The Shiv.\"", objectives = "Travel to Stormwind and seek out Renzik \"The Shiv.\"", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2299] = { title = "To Hulfdan!", description = "Where have you been, $N? Hulfdan's been looking all over the place for you. We thought the king may have put you in irons.\n\nGet to Ironforge as soon as possible and speak with Hulfdan!", objectives = "Travel to Ironforge and speak with Hulfdan Blackbeard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2300] = { title = "SI:7", description = "Renzik was looking for you, fish.\n\nI wouldn't keep Mathias's second in command waiting if I were you.", objectives = "Travel to Stormwind and seek out Renzik \"The Shiv.\"", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2318] = { title = "Translating the Journal", description = "At an impasse of sorts, you know that you will need the book translated into a language you can understand.  There certainly are a number of people in the world who could do it; the closest location that might have someone who could, however, is the Kargath outpost in the Badlands.  Perhaps that is a good place to start.", objectives = "Find someone who can translate the paladin's journal.  The closest location that might have someone is Kargath, in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2338] = { title = "Translating the Journal", description = "Droffers and Son Salvage aren't smart enough to restore the magic in the necklace, but I am.  All I want to do is study the necklace so I can learn to make them myself.  To do that, I will need your necklace.  Let me borrow it, and in exchange for the time I get to study it I will translate the journal for you.  While you are searching for the gems, I should have enough time to learn what I need to.\n\nIt's a simple deal, and no one else will be the wiser.  Whatcha wanna do?", objectives = "Let Jarkal borrow the necklace.  In exchange, he will translate the journal for you.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2339] = { title = "Find the Gems and Power Source", description = "Here is the journal, translated for you to read on your own.  The crux of it says dwarves hid the ruby, the troggs hid the topaz, and a trogg named Grimlok has the sapphire.\n\nLook - you're going to need a power source to make the necklace work again.  Dran Droffers doesn't know this.  To find one, here's what I'd do: go as deep as you can in Uldaman and kill whatever construct there is the strongest.  No doubt whatever that is would have it.\n\nWhen you have everything collected, come back here!", objectives = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath.  Jarkal believes a power source might be found on the strongest construct present in Uldaman.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n* The sapphire has been claimed by Grimlok, the trogg leader.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2340] = { title = "Deliver the Gems", description = "Any necklace setting and gem will work, so long as they are the same material.  This power source, however, is what will bring the magic back to the necklace... I hope.\n\nI'll gladly supply the gems needed for your version of the necklace, so long as the power source actually works.\n\nHead to Orgrimmar and keep your end of the bargain with Droffers and Son Salvage.  Just keep your mouth shut about our deal, and when you get back I might have a wonderful surprise for you.", objectives = "Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2341] = { title = "Necklace Recovery, Take 3", description = "As Dran and Malton Droffers begin to squabble over their new salvage, half of the deal is now complete.  A trip to the Badlands is now in order to finish things up, as Jarkal Mossmeld in Kargath might have a special reward waiting for you there.", objectives = "Visit Jarkal Mossmeld in Kargath to see if he was successful.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2342] = { title = "Reclaimed Treasures", description = "Sweeping the bat pens with this broom is not befitting a Garrett!  I've earned a little coin from this accursed job, and I'm willing to spend it on you to better my station.\n\nThe Garrett family weapon of choice is locked away in our chest in the South Common Hall of Uldaman from when we Garretts toiled there as diggers.  Without it, I will be stuck here forever - literally - sweeping up after these infernal bats.\n\nReclaim my family's treasure and bring it to me!  Help me restore my birthright!", objectives = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2358] = { title = "Horns of Nez'ra", description = "Many years ago, the Horns of Nez'ra were stolen from Ravenholdt manor. Across continents and oceans I have searched, only to discover that these insignificant beasts have had it in their possession all along.\n\nSlay every Blackrock orc you cross until the Horns of Nez'ra are recovered. Should you recover the horns, find me in Lakeshire.\n\nDo this for me and your name shall be known to Ravenholdt, $N.", objectives = "Return the Horns of Nez'ra to Arantir's Shadow in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2359] = { title = "Klaven's Tower", description = "I've been staking out this tower for weeks, $N. Recently a major shipment came through from Duskwood, and along with it came those guards.\n\nWhat are they? Your guess is as good as mine. I can tell you one thing - they aren't human.\n\nAnyhow, the shipment had a chest - which is what I assume those abominations are guarding. The zombie with the spikes holds a key we'll need.\n\nGet that key, get in the tower, and uncover whatever is in that chest. Take your findings back to Mathias.", objectives = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2360] = { title = "Mathias and the Defias", description = "Not a moment too soon, $N. SI:7 reconnaissance is reporting unusually heavy Defias activity in Westfall.\n\nIt would seem that the Defias have taken over an abandoned Alliance watch tower southeast of Sentinel Hill and are using it as a base of operations to smuggle in goods from the Redridge supply route.\n\nGet to Westfall and contact Agent Kearnen for your debriefing. You will find her hidden near the tower.\n\n...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence. ", objectives = "Travel to Westfall and find Agent Kearnen for your debriefing.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2361] = { title = "Restoring the Necklace", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2378] = { title = "Find the Shattered Hand", description = "You have served the Deathstalkers well, $N, but perhaps it is time for you to venture outward. While you have shown aptitude in the ways of stealth and deception, you still require much training.\n\nThe Deathstalkers have allies within the Shattered Hand. Seek out those that would assist us - find Shenthul in Orgrimmar.", objectives = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2379] = { title = "Zando'zan", description = "Your determination alone is not enough to overcome the obstacles that lay ahead of us.\n\nSpeak with Zando'zan to begin your training as an operative of the Shattered Hand.\n\nIt is only when you have mastered the practices of stealth and thievery that you may take the next step towards your destiny.", objectives = "Speak with Zando'zan at the Cleft of Shadow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2380] = { title = "To Orgrimmar!", description = "A master of stealth and deception you are not, however, all of that can and will change. You've obviously impressed those in charge with your meager skills, as the great Shenthul has asked for you by name.\n\nTake the road north of here to Orgrimmar and speak with Shenthul in the Cleft of Shadow.", objectives = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2381] = { title = "Plundering the Plunderers", description = "I don't mean to scare you, $N, but the last five thieves I sent to steal the southsea treasure came back to me in pieces.\n\nSouth along the coast you'll find Tide Razor, the southsea freebooter's ship. Nestled in the hold is the payoff - the southsea treasure. On the second level of that ship is the pirate's den, a place where they train all of their thieves.\n\nBoard that ship, steal the treasure, and bring it back to me. Use the pirate's den if you need to practice your thievery, but be careful!", objectives = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.\n\nShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2382] = { title = "Wrenix of Ratchet", description = "Zando'zan has seen it! Yes, the day comes! Thrall's death... the dagger in his back, poison seeping through to his every vein... Zando'zan has said too much.\n\n$N! Zando'zan has a task for $N! $N must travel to Ratchet, east of the Crossroads, and speak with Wrenix the Wretched. Go!", objectives = "Travel to Ratchet and speak with Wrenix the Wretched.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2383] = { title = "Simple Parchment", description = "Ah, while you were gone a parchment came for you, $N.\n\nRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.", objectives = "Read the Simple Parchment and speak to Frang in the Valley of Trials.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2398] = { title = "The Lost Dwarves", description = "The dig site at Uldaman wasn't always overrun.  We Ironforge dwarves used to control the area, but... that was before the troggs came.  They came so fast and in such numbers that not even dwarven might could stop them!\n\nIn fact, their attack was so sudden that I fear some of our people may be trapped behind enemy lines.\n\nMy friend Baelog led a small band of dwarves deep within the site just before the troggs showed up.  If he and his company live, then I want you to find them.", objectives = "Find Baelog in Uldaman.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2399] = { title = "The Sprouted Fronds", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2418] = { title = "Power Stones", description = "A while ago, I had an incident with the Shadowforge Dwarves.  They brought me to Angor Fortress to study two types of strange stones from Uldaman.  I discovered that the stones were sustained, stable power sources if treated correctly.  It's amazing the things one can find in that old dig site!\n\nAnyway, after I told them the secret of the stones they kicked me out of Angor Fortress and began digging for more in Uldaman.\n\nI want those stones for myself!  Bring me both types and I'll pay you plenty!", objectives = "Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2438] = { title = "The Emerald Dreamcatcher", description = "I was once given an emerald dreamcatcher from Gaerolas Talvethen, the warden of the druids in the Ban'ethil Barrow Den. This powerful amulet is able to siphon energy from the Emerald Dream, bestowing luck upon those who carry it.\n\nSadly, I have not been able to retrieve it from my dresser in Starbreeze Village... Although Starbreeze was once a tranquil place, it has now succumbed to the corruption of the furbolg that reside there.\n\nPerhaps you would be willing to recover my dreamcatcher, $c? ", objectives = "Bring the Emerald Dreamcatcher to Tallonkai Swiftroot in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2439] = { title = "The Platinum Discs", description = "This object is an incredible find.  The ancient Titans, or the Creators as these discs refer to them as, are the link to our enchanted creation, if the lore stored in here is correct!  We'll need to invest as much research time into this as possible.\n\nAs for you, heroic $c, take this voucher to Dinita Stonemantle at the vault.  It grants you what I think is a fitting for such a tremendous find!\n\nReturn to me directly when you are ready; there is much more to do for the Explorers' League!", objectives = "Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2440] = { title = "The Platinum Discs", description = "I shall focus my energies on these discs; they will reveal their true workings to me in due time.\n\nAs for you $N, I will now reward you for your diligence in bringing this to my attention.  Take this voucher to Bena Winterhoof, the alchemy trainer for Thunder Bluff.  She will give you a special item I believe you will find appealing, and she will supply you with a choice of potions from my personal stock.\n\nReturn to me soon, as I sense there is much more at hand for us to do regarding this find.", objectives = "Take the reward voucher to Bena Winterhoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2458] = { title = "Deep Cover", description = "The Venture Company... Perhaps you have heard of them?\n\nFor one year we have worked on planting an agent deep within their ranks. Through much hard work and careful planning, we succeeded.\n\nRecently we received word that the Venture Co. are planning something on a grand scale. Go north of the Sludge Fen to the Venture Co. tower and contact our undercover agent, Taskmaster Fizzule.\n\nWhen you find the tower, use this flare gun, then approach Fizzule and show him the salute of the Shattered Hand.", objectives = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\n\nWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\n\nThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2459] = { title = "Ferocitas the Dream Eater", description = "The emerald... It is missing! My dreamcatcher has been damaged!\n\nThere is a band of Gnarlpine mystics located to the north of Starbreeze. I have heard reports that their leader, Ferocitas the Dream Eater has been wearing a necklace that glows green in the night. Now seeing my dreamcatcher, I am sure that he has stolen my emerald... He would never realize that its power is useless to him.\n\nFind this missing jewel, $N. And, while you're there, clear out some of the corrupted mystics as well.", objectives = "Tallonkai Swiftroot in Dolanaar wants you to kill 7 Gnarlpine Mystics and find the Missing Jewel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2460] = { title = "The Shattered Salute", description = "As a rogue of the Shattered Hand, it is imperative that you learn the Shattered Salute. It is the only way to truly identify another member of the Hand.\n\nWatch, learn, repeat.", objectives = "Perform the Shattered Salute on Shenthul.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2478] = { title = "Mission: Possible But Not Probable", description = "You will need to steal the tower key from Foreman Silixiz, $N. Once you've got the key in your possession, hold on to it - I may need it later.\n\nRemember, the poison has weakened everything in this tower. Use your abilities to bring chaos and destruction to its inhabitants. Slay them all -- show no mercy!\n\nOnce everything inside lays in a bloodied heap, pick Gallywix's lockbox and steal the cache of Zanzil's mixture held inside. Take both the head of Gallywix and the mixture to Shenthul in Orgrimmar.", objectives = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.\n\nAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2479] = { title = "Hinott's Assistance", description = "Take a sample of the mixture to Serge Hinott in Tarren Mill.\n\nIf anyone can cure you, it's Serge. Live long enough and Serge will show you the ways of poison creation and use.", objectives = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\n\nTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2480] = { title = "Hinott's Assistance", description = "I have never seen such wondrous results from a poison! Zanzil you say? Never heard of him, however, I must commend him on the creation of this concoction.\n\nSo, I am to cure you of this and then teach you how to make use of the poison?\n\nGive me a few moments to examine the toxin, $N.", objectives = "Wait for Serge Hinott to complete the cure.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2498] = { title = "Return to Denalan", description = "I have just received word that  Denalan at Lake Al'Ameth has discovered what may be the cause of the tumors that plague the timberlings. Please speak with him, and tell him I sent you.\n\nMake haste, $N; he needs our help.", objectives = "Rellian Greenspyre wants you to speak with Denalan at Lake Al'Ameth.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2499] = { title = "Oakenscowl", description = "In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home.\n\nI dared not get too close, but even from a distance, it is obvious: Oakenscowl is being poisoned by the largest tumor I have ever seen...  I would call it gargantuan, even.\n\n$N, you have already done much to aid my efforts, but I ask of you one more task. Hunt down Oakenscowl and collect the tumor; remove this source of corruption from my home.", objectives = "Denalan at Lake Al'Ameth wants you to collect the Gargantuan Tumor from Oakenscowl.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2500] = { title = "Badlands Reagent Run", description = "$C, I would make use of your services.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.\n\nWell, what say ye?", objectives = "Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2501] = { title = "Badlands Reagent Run II", description = "You have been most helpful to me, $N.  I would like to reward you with the very recipe for the brew I gave you earlier, but I must ask of you a favor that is quite dangerous.\n\nThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be careful.  Once you have all three filled, bring them to me.\n\nDo this, and the recipe will be yours.", objectives = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Ghak Healtouch in Thelsamar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2518] = { title = "Tears of the Moon", description = "Lady Sathrah was once beloved of Elune. Graceful and pure, the spider spun her silver threads through the moonlight, catching the evening mist. The silvery dew had strong healing powers and was kept here in the temple.\n\nBut of late, Sathrah has descended into madness. Her future generations are now threatened as well.\n\nFind Lady Sathrah, $N, and end her suffering. She dwells along the northern borders of Teldrassil, near Wellspring Lake. Gather her silvery spinnerets and bring them back to me.", objectives = "Priestess A'moora in the Temple of the Moon at Darnassus wants you to bring her Lady Sathrah's Silvery Spinnerets.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2519] = { title = "The Temple of the Moon", description = "A once great creature of the forest is in need of help, $r.\n\nThere is a difficult task that must be done.\n\nPlease seek out Priestess A'moora; she will explain things to you. Find her to the southeast of here, inside the Temple of the Moon.", objectives = "Sister Aquinne wants you to speak with Priestess A'moora in the Temple of the Moon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2520] = { title = "Sathrah's Sacrifice", description = "Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest.\n\nInside this temple, find the central fountain. There is where you may leave the sacrifice.  The holy waters will purify and cleanse the corruption that drove Sathrah mad.\n\nWhen you have completed this, return to me.", objectives = "Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2521] = { title = "To Serve Kum'isha", description = "$R, can your miniscule brain comprehend the rarity of a flawless sphere of draenethyst? Draenei have spent lifetimes in search of just one of these crystals, only to meet horrible fates, their purpose unfulfilled.\n\nSo you stand before Kum'isha, knowing what Kum'isha has requested and still wish to assist? Very well, $r... At any time during your travels across these lands, should you find a flawless sphere of draenethyst, return it to me and I shall reward you with riches beyond your wildest dreams.  ", objectives = "In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.\n\nBe warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.\n\nYou will be rewarded for each Flawless Draenethyst Sphere you have collected.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2522] = { title = "Kum'isha's Endeavors", description = "Even though the portal conjuration was a failure, I remain hopeful that my next attempt will be successful.\n\nThe hope of the Draenei is as fervent as your greed for trinkets, $r. Go back out into these cursed lands and recover another flawless draenethyst sphere.\n\nOf course, the choice to take on this task is completely left to you *grin*.", objectives = "Find and return a Flawless Draenethyst Sphere to Kum'isha the Collector.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2523] = { title = "Corrupted Songflower", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2541] = { title = "The Sleeping Druid", description = "The Gnarlpine shaman that inhabit this place have discovered a way of separating a sleeping druid's spirit from the physical body. The furbolg have animated my physical form and are using it to attack anyone that attempts to explore the Ban'ethil Barrow Den. I am now trapped in the Emerald Dream, powerless to stop this.\n\nYou must help me. The Gnarlpine shaman carry a strange charm which is used to perform this ritual, and I'd like to examine it. Please, $N, bring one to me.", objectives = "Bring a Shaman Voodoo Charm to Oben Rageclaw in the Ban'ethil Barrow Den.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2561] = { title = "Druid of the Claw", description = "After examining this charm, $N, I see now what must be done. Please take it, and do as I ask.\n\nYou are to explore the deepest areas of the Ban'ethil Barrow Den. There, you will find my soulless body... Although I regret what I am about to tell you, I see no other way to free myself from the control of the Gnarlpine.\n\nIn order for me to escape them, you must kill my physical form.  Once that is done, use the voodoo charm on my fallen body. After you have completed this task, please return to me.", objectives = "Oben Rageclaw wants you to kill his soulless body, and then use the Voodoo Charm.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2581] = { title = "Snickerfang Jowls", description = "It is a well known fact that hyenas possess tremendous strength in their jowls, but the strength to snap through three inches of thorium steel? Impossible, improbable, and yet I have seen this demonstrated with my own eyes.\n\nVenture forth, into the Blasted Lands, and bring me three snickerfang jowls. As you search for the snickerfang, be on the lookout for boars and scorpoks: The initial assay also requires two blasted boar lungs and one scorpok pincer to complete.", objectives = "Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2582] = { title = "Rage of Ages", description = "Ah, $N, welcome back. It seems you enjoyed the effect of the robust, operational imbue, derived from snickerfang. Be warned, while the immediate effect is a titanic burst of strength, the long term effects on your spirit and intelligence could be hazardous.\n\nWith that said, do you require more? If so, bring me another three snickerfang jowls, two blasted boar lungs, and one scorpok pincer.", objectives = "Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2583] = { title = "A Boar's Vitality", description = "Within these blasted lands exists two species of boar: the ash-mane boar and the helboar.\n\nIt would appear that the stamina of these beasts renders them nearly immune to harm, as the other animals find them too difficult to kill and consequently, not worth the effort.\n\nWe need to perform further analysis, $N. Should you bring me three blasted boar lungs, two scorpok pincers, and one basilisk brain, I shall create a divine elixir from the residue of the assay. You will be my first test subject!", objectives = "Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2584] = { title = "Spirit of the Boar", description = "When I first administered the elixir, $N, I could tell that one or two applications would not satiate your appetite. Even now, I can see the hunger in your eyes. The concoction has addictive properties of which, seemingly, the most strong of will cannot resist.\n\nSo be it! Should you require more of the lung juice cocktail, venture back into the wasteland and find for me three blasted boar lungs, two scorpok pincers, and one basilisk brain.", objectives = "Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2585] = { title = "The Decisive Striker", description = "Have you ever watched them in battle, $N? The scorpoks, I mean. Have you ever seen the grace and agility with which they move? The decisiveness of their strikes?\n\nIf only we could somehow isolate that agility and encapsulate it, we would be wealthy beyond our... I mean... it would be a boon for the scientific community.\n\nAssist me, $N, and I shall allow you a sampling of the assay.\n\nIn order to create a stable sample, I will need three scorpok pincers, two vulture gizzards, and one blasted boar lung.", objectives = "Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2586] = { title = "Salt of the Scorpok", description = "You live! This is good news, indeed. I assume you are back for more of the scorpok assay?\n\nVery well, $N, back to the wasteland with you and do not return until you have collected three scorpok pincers, two vulture gizzards, and one blasted boar lung.", objectives = "Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2601] = { title = "The Basilisk's Bite", description = "These wastelands are riddled with redstone basilisk, $N. These basilisk have adapted and flourished, more so than any of the other wildlife within the region.\n\nI have watched from afar as they hunt and go about their daily activities - the beasts exhibit a thought process more complex than even some humanoids.\n\nI must study their brains!\n\nRetrieve ten of their brains for me, $N. The compound cannot be complete, however, without two vulture gizzards to form the base of the solution.", objectives = "Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2602] = { title = "Infallible Mind", description = "Your focused concentration has dwindled so soon? More research must be done!\n\nOh yes, the price remains the same, $N. Venture forth into the blasted lands and return to me with ten brains from the redstone and two vulture gizzards.", objectives = "Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2603] = { title = "Vulture's Vigor", description = "Death does indeed have wings in these blasted lands, $r. I have witnessed the black slayers and bonepickers feasting upon the corpse of many a fallen explorer - sometimes feeding upon the most vile and disease ridden of carcasses. It is a wonder, then, how their internal systems overcome the pestilence that claims these lands.\n\nAssist me in my studies, $N! Gizzards I need! Two snickerfang jowls will also be required for the base of the concoction.\n\nYou shall be rewarded two-fold for your efforts.", objectives = "Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2604] = { title = "Spiritual Domination", description = "I see that the inner fire has dwindled. Would you say the spiritual euphoria lasted an hour?\n\nIf it's more of the gizzard gum you desire, then more of the gizzards I require. Back to the wastelands, $N. Do not return until you have recovered ten gizzards and two jowls.", objectives = "Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2605] = { title = "The Thirsty Goblin", description = "I've got an idea, see. I've heard of some strange creatures called dew collectors that live to the southwest... and that they are able to store water in special glands.\n\nI think that if I could get one of these glands, I could create a drink that would quench my terrible thirst! Do you think you could help me, $N?\n\nLook for the cactus garden, $N; that's where you'll find the dew collectors.", objectives = "Collect a Laden Dew Gland and bring it to Marin Noggenfogger in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2606] = { title = "In Good Taste", description = "Blech! This stuff tastes terrible! So much for that idea...\n\nWait, what's that? Oh, I know, I know, you think I shouldn't give up on this stuff. Well, okay then.\n\nUhhhh, I have an idea! Brilliant! Take this dew to my friend Sprinkle -- she's an excellent chef. Tell her what we're up to here and that we want to make it go down a little easier.\n\nI mean, if it's going to taste that bad, it at least should have some kick to it... And I'm just not feeling it... ", objectives = "Marin Noggenfogger wants you to speak with Sprinkle in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2607] = { title = "The Touch of Zanzil", description = "It appears as if you've brought back more information than even I expected. This certainly is a strange turn of events, $N.\n\nA cure? Hrm... Go down to the cellar and speak with Doc Mixilpixil - he may be able to help.", objectives = "Speak with Doc Mixilpixil in the cellar of the Barracks.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2608] = { title = "The Touch of Zanzil", description = "Oh my, you look like death. Correction - I've seen death, you look worse than death. You, $g sir:miss;, would be what death coughed up at his last physical.\n\nHah! You hear that Noarm? Write that one down!\n\n*Cough* Hrm yes, in order for me to help you, I'll need to draw some blood. Don't worry, it only hurts the first few... fifty times or so... /lay down when you're ready for the treatment, $N.", objectives = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2609] = { title = "The Touch of Zanzil", description = "It's unanimous, $N. You've got the 'itis.'\n\nLuckily, I have a cure for the 'itis.'\n\nHere's what I need: One bundle of simple wildflowers, one leaded vial, one bronze tube, and last but certainly not least, one spool of light chartreuse silk thread. Ol' Emma left a spool of it for me at 'The Finest Thread.' You can find the shop along the canals.\n\nHurry along now, $N, and try not to touch anyone until you're cured. Oh, and Dr. Montgomery says you need a shower -- his words, not mine.", objectives = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young $g fella:lady;. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2621] = { title = "The Disgraced One", description = "Regret. It is all I have now. One bad decision resulting in several horrible outcomes. If only I had waited for those orders. Maybe they would have detailed the horrors that awaited us in those cursed lands! Maybe they were to redirect us to another detail? Ultimately, it was my fault. All of it was my fault.\n\nSo here I stand, awaiting orders. I must know. I must have those orders.\n\nDispatch Commander Ruag resides in Stonard. Find him and find out what became of the orders.", objectives = "Speak to Dispatch Commander Ruag in Stonard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2622] = { title = "The Missing Orders", description = "The orders? What could you possibly want with the orders?\n\nWhat are you implying, $N? Of course I relayed those orders! The soldiers I sent the orders with were ambushed and brutally beaten by murlocs. Only one survived, if you can call that surviving. He can hardly speak, cannot walk, and must be fed through a tube. If you want to know what happened to those orders, speak with Bengor. I'm sure he is around here somewhere... and, $N, be mindful of what you stick your nose into - it may get bitten off.", objectives = "Speak to Bengor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2623] = { title = "The Swamp Talker", description = "Orders were given by the dispatch commander. We took... took orders. On way to Blasted Lands, ambushed.\n\nMurlocs... Many murlocs... One named Swamp Talker. Took orders from my hands as spear thrust into my skull. East... cave....\n\n<Bengor passes out.>", objectives = "Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2641] = { title = "Sprinkle's Secret Ingredient", description = "When I was a kid, my sister used to do all the cooking. It was horrible! I could barely stomach some of her concoctions -- until I found what I like to call my \"secret\" ingredient! Add it to anything, and... WOW! It tastes great!\n\nWhat is it, you ask? It's a mushroom called the Violet Tragan. If you want me to help you turn this horrid-tasting brew into something edible, head to the Hinterlands, and look for a small lake there.\n\nOh, and remember, the Violet Tragan can only be found underwater.", objectives = "Sprinkle in Gadgetzan wants you to collect a Violet Tragan and return it to her.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2661] = { title = "Delivery for Marin", description = "Here's the Violet Powder, $N. Take it to Marin and tell him he owes me a favor!", objectives = "Sprinkle wants to you take the Violet Powder to Marin Noggenfogger in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2662] = { title = "Noggenfogger Elixir", description = "Now, to mix this powder in with the dew.\n\nCome back and talk to me in a minute... after I have perfected the fabulous Noggenfogger Elixir!", objectives = "Marin Noggenfogger wants you to speak to him again after he creates his elixir.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2681] = { title = "The Stones That Bind Us", description = "It will take more than you alone to overcome the forces of Razelikh and his subordinates.\n\nGather a suitable group of adventurers and free my men of their eternal torture! Eighteen stones you must shatter.\n\nFight hard and die with honor, $N.", objectives = "Free nine Servants of Razelikh, three Servants of Sevine, three Servants of Allistarj, and three Servants of Grol. Return to the Fallen Hero when your task is complete. You must remain within close proximity of the stones or the process will fail.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2701] = { title = "Heroes of Old", description = "Please, take from this a relic of old. We no longer have a use for the item.\n\nMay it serve you well in your fight against the legion.", objectives = "Open the chest and claim your reward.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2702] = { title = "Heroes of Old", description = "You have honored me with your nobility and heroism, $N.\n\nYou have also honored them...", objectives = "Speak to Corporal Thund Splithoof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2721] = { title = "Kirith", description = "As one chapter of your adventure closes, another one begins, $N.\n\nOne of my men is still unaccounted for, lost somewhere in the Blasted Lands. I am talking about Lieutenant Kirith, of course.\n\nAs I had mentioned earlier, we were both imprisoned and tortured by Allistarj, but poor Kirith, his strength of will faltered. I could hear the experiments from my cage; the tortured screams rang through the halls of the cave. That was the last I saw or heard of Kirith.", objectives = "Find out what became of Lieutenant Kirith.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2741] = { title = "The Super Egg-O-Matic", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2742] = { title = "Rin'ji is Trapped!", description = "Hey $r!\n\nRin'ji lost axe and was captured! Please, help Rin'ji escape. Me know that $r like you don't like Rin'ji's kind, but Rin'ji begs! Must get out of here!\n\nGot something for nice $r if $Ghe helps Rin'ji out of here:she helps Rin'ji out of here;...\n\nRin'ji is hiding something secret at the Overlook Cliffs.", objectives = "Escort Rin'ji out of the Quel'Danil Lodge, then find his hidden secret at the Overlook Cliffs to the east.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2743] = { title = "The Cover of Darkness", description = "Let us not mince words, $r; my time here is limited.\n\nYou must destroy the triad of power which protects the demon lord, Razelikh. Doing so will not be as simple a task as freeing a damned soul.\n\n<Kirith grins.>\n\nYou see, each of Razelikh's underlings wears a third of an amulet of Razelikh's creation around their neck. The very same amulet you will need in order to summon the arch demon.\n\nReturn to Trebor and tell him what is required to summon Razelikh. He will be able to instruct you further.", objectives = "Return to the Fallen Hero of the Horde with your findings.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2744] = { title = "The Demon Hunter", description = "The triad is protected by Razelikh.\n\nIn exchange for their servitude, Razelikh granted each of them nearly unlimited power within the Blasted Lands. The amulet pieces are each attuned to the lifeforce of their owner, granting them immortality. As long as they remain within the Blasted Lands, they cannot be slain, their life spans extended until the end of days.\n\nThere is one who may be able to assist you further, $N. Travel to Azshara and find the demon hunter, Loramus Thalipedes. Search the islands.", objectives = "Speak with Loramus Thalipedes in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2745] = { title = "Infiltrating the Castle", description = "Hmm, an interesting tale, and not one to be taken lightly. Yeah, I can help you, but what you need to do is divvy out a form of justice that's not... legal, if you're to see this through to the end.\n\nLescovar and Marzon need to be dealt with, and swiftly. Do you think you're capable of such a thing?\n\nYou decide. If so, then make haste to the castle and find an old friend of mine, a gnome named Tyrion. He's been watching Lescovar now for a couple weeks. He should be able to help you end this.", objectives = "Speak to Tyrion in Stormwind Castle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2746] = { title = "Items of Some Consequence", description = "Trias wants the timetable pushed up some, huh? Okay, we can do that, but I'm not ready. And know this, I'm doing the hard part, but you're the one that's going to get $g his:her; hands dirty, understand? Good.\n\nOkay, I'll need you to get me a few things before I can put my plan into effect. I got the perfect disguise that'll get Spybot past those guards.\n\nBring me some silk and a couple apples. The silk's up to you, but Clara's little farm right outside the city has the perfect sized apples.", objectives = "Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2747] = { title = "An Extraordinary Egg", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2748] = { title = "A Fine Egg", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2749] = { title = "An Ordinary Egg", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2750] = { title = "A Bad Egg", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2751] = { title = "Barbaric Battlements", description = "Twenty generations of Omosh have held this hammer, $N. A hundred thousand tons of metal we have molded. Tragically, it all ends at Orokk, failure of the Omosh: Without kin and incapable of producing offspring.\n\nI cannot let the secret recipes of Omosh die with me! Someone must continue the legacy, Omosh or not!\n\nProve to Orokk you are capable, $N. Bring for Orokk the following: Two patterned bronze bracers, two bronze greatswords, and two sharp claws. Bring them for Orokk and we shall continue.", objectives = "Bring two Patterned Bronze Bracers, two Bronze Greatswords, and two Sharp Claws to Orokk Omosh in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2752] = { title = "On Iron Pauldrons", description = "Orokk sees the eagerness in your eyes, $N. Like a sponge you soak in the wisdom of the Omosh.\n\nThree lessons I shall teach!\n\nReturn to the anvil, soak in the heat of the forge, create for Orokk four bronze battleaxes and four bronze warhammers. Only then will you learn of the iron pauldron.", objectives = "Bring four Bronze Battleaxes and four Bronze Warhammers to Orokk Omosh in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2753] = { title = "Trampled Under Foot", description = "Only two more lessons Orokk will teach, $N. Your muscles ache, I know, but continue on for the Omosh!\n\nBring to Orokk four green iron helms, four green iron bracers, and two green iron leggings - for this you learn and your enemies suffer!", objectives = "Bring four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings to Orokk Omosh in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2754] = { title = "Horns of Frenzy", description = "The final lesson Orokk teaches you, $N. To the sacred anvil and forge you return! Bring for Orokk two solid iron mauls, two silvered bronze boots, and two silvered bronze gauntlets.\n\nSee the fear in their eyes as you approach!", objectives = "Bring two Solid Iron Mauls, two Silvered Bronze Boots, and two Silvered Bronze Gauntlets to Orokk Omosh in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2755] = { title = "Joys of Omosh", description = "Orokk is not crying, $N. Soot is in eye.\n\n<Orokk wipes a tear away.>\n\nThere is one last Omosh family secret Orokk will teach you. Orokk will die happy, thanks to $N.\n\nLearn Omosh dance of joy and then you learn fist of iron!", objectives = "Watch and learn the Omosh Dance of Joy.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2756] = { title = "The Old Ways", description = "In the time of legends, Aturk would crush the skulls of his enemies and grind the bone into a fine powder for use in filament. Long gone are those days, $r. The Warchief calls for peace among the clans. Old enemies are now only watched with weary eyes!\n\nUnbelievable, I know, but such is the will of Thrall.\n\nEnough lamenting! You are here to learn, and learn you will! Bring me four steel breastplates and four steel helms and you will gain a taste of war!", objectives = "Bring four Steel Breastplates and four Steel Plate Helms to Aturk the Anvil in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2757] = { title = "Booty Bay or Bust!", description = "Listen, kid, you're not gonna learn anything hanging around here.\n\nI know a guy who knows a guy. He hangs around the smithy in Booty Bay. If you show him this insignia, he'll tell you all about mithril.\n\nSo whadd'ya say? Leave this kid stuff to the babies in diapers, $N -- it's time to move on.\n\nIf you're interested, his name's McGavan. Show him this trinket and he'll recognize your commitment.", objectives = "Speak with McGavan in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2758] = { title = "The Origins of Smithing", description = "When I was about your age, a dwarf by the name of Galvan took me under his wing and trained me in the ways of the armorsmith. Before he left for Booty Bay, he made me promise to train all those with the desire and determination to advance in the craft of blacksmithing -- so here I am -- all these years later.\n\nSo, now it's time for you to learn a little something. Make me six golden scale bracers and you will learn where smithing comes from, $N.", objectives = "Bring six Golden Scale Bracers to Hank the Hammer in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2759] = { title = "In Search of Galvan", description = "Although Galvan left Booty Bay many years ago, members of the order still remain in town, hoping to one day find another worthy of Galvan's tutelage.\n\nTake this insignia and present it to McGavan in Booty Bay.\n\nIf you actually make it that far, he'll know that you are worthy. I have faith, $N!", objectives = "Speak with McGavan in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2760] = { title = "The Mithril Order", description = "Most of our recruits never make it to Booty Bay, $N. The shine of the insignia is enough to trigger the loot lust in even the staunchest of blacksmiths. Fools they be, as the insignia is a drop in the bucket compared to the wealth of items you'll see!\n\nFind Galvan the Ancient and show him this pin. His residence is far to the north, between Zul Gurub and the Mosh'Ogg ogre mound.", objectives = "Speak with Galvan the Ancient in Stranglethorn Vale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2761] = { title = "Smelt On, Smelt Off", description = "Many blacksmiths believe that mining and smithing are separate, independent jobs; but can there be blacksmithing without mining? Ah ha -- it is an impossibility! The accomplished blacksmith must also be an accomplished miner.\n\nShow Galvan that you are capable, $N. Bring me forty bars of iron and forty bars of mithril. For this, Galvan will teach you the ways of the ornate mithril pants!", objectives = "Bring forty Mithril Bars and forty Iron Bars to Galvan the Ancient in Stranglethorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2762] = { title = "The Great Silver Deceiver", description = "It is said that truesilver is stronger and more durable than mithril. Galvan does not disagree with this assessment of the minerals, but contrary to its name, truesilver is not true! Mithril is a far nobler mineral! HAH! Regardless, for this lesson you will need to find the great silver deceiver, $N.\n\nBring me forty bars of mithril and five bars of truesilver. In exchange, you will be taught the secret of ornate mithril gloves and more importantly, learn that truesilver is a liar!", objectives = "Bring forty Mithril Bars and five Truesilver Bars to Galvan the Ancient in Stranglethorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2763] = { title = "The Art of the Imbue", description = "The harvesting of precious gems is of utmost importance to our craft, $N. Few gems are more precious than the citrine. The magical properties we imbue into our goods are amplified greatly by the presence of citrine.\n\nFor this lesson, we will fortify forty bars of mithril with four citrines. The result will be a better understanding of magical gemology and the knowledge to create ornate mithril shoulders.", objectives = "Bring forty Mithril Bars and four Citrines to Galvan the Ancient in Stranglethorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2764] = { title = "Galvan's Finest Pupil", description = "If you are ready to conclude your training with Galvan, you should journey to Gadgetzan.\n\nThere, you will find my finest pupil: Trenton Lighthammer. He has much to teach you in the ways of ornate mithril. Otherwise, remain here and learn!\n\nOh, Gadgetzan is in Tanaris, of course!", objectives = "Speak with Trenton Lighthammer in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2765] = { title = "Expert Blacksmith!", description = "When you first came to me, I knew that you would turn out to be one of my finest pupils! It was without hesitancy that you gave up a trinket of some power to McGavan. You did this only so that you could meet me. Such blind faith and devotion to the craft should be rewarded.\n\nYou have attained expertise over blacksmithing, $N. Reap the rewards!", objectives = "Claim your reward from Galvan the Ancient!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2766] = { title = "Find OOX-22/FE!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"", objectives = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2767] = { title = "Rescue OOX-22/FE!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the dock along the Forgotten Coast!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely to the dock, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", objectives = "Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2768] = { title = "Divino-matic Rod", description = "Sergeant Bly stole from me!  He said he'd only borrow it, but he stole my cherished divino-matic rod!!  Without that rod how will I know where to dig new water holes??\n\nFind Bly and bring me my rod!  I heard he led his band of ill-reputed adventurers to go treasure hunting in Zul'Farrak to the west.  I bet you'll find him there.\n\nLet's hope the trolls took care of him, because if you have to fight him for the rod then you're in for a serious fight.", objectives = "Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2769] = { title = "The Brassbolts Brothers", description = "Have you met the Brassbolts brothers?  They're over in the Shimmering Flats, in Kalimdor, racing their rocket car against the goblins.  They usually win which is no surprise--the goblin car blows up so much it barely ever crosses the finish line!\n\nBut even then, the Brassbolts brothers are always looking for new ways to make their car go faster, and Wizzle told me he needs a very rare component for his next experiment.\n\nHe probably needs help getting that part.  Speak to him and find out.", objectives = "Speak with Wizzle Brassbolts in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2770] = { title = "Gahz'rilla", description = "Deep in Zul'Farrak, the sand troll city in Tanaris, there is a sacred pool.  From that pool the trolls summon a huge beast!  Gahz'rilla!  He's so fierce that even his scales crackle with energy.  It's that energy I want to harness for my car!\n\nBring me the electrified scale of Gahz'rilla!\n\nBut the summoning of Gahz'rilla is a well-kept secret of the trolls.  To face him, you must first wrest the secret from them.", objectives = "Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2771] = { title = "A Good Head On Your Shoulders", description = "It seems as if master had this planned from the start. I was not taught to create the items which you learned to create and you were not taught the items which I learned to create.\n\nThe master is wise, $N. We shall teach each other!\n\nShow me how to make a mithril coif and ornate mithril shoulders and I shall show you how to create an ornate mithril helm.", objectives = "Bring two Mithril Coifs and one Ornate Mithril Shoulder to Trenton Lighthammer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2772] = { title = "The World At Your Feet", description = "At last year's All-Valley Blacksmithing Championship, all those who watched saw my leg get swept from under me by a cowardly dog from the Venture Co. Foundry. What they didn't know, however, was the reason I was able to continue and ultimately win the tournament: That's right, ornate mithril boots!\n\nI will need to learn how to craft ornate mithril pants for this year's tournament, however, as a Venture Co. shredder is an entrant! Teach me the way of the pants and learn the way of the boot!", objectives = "Bring two Heavy Mithril Boots and one Ornate Mithril Pants to Trenton Lighthammer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2773] = { title = "The Mithril Kid", description = "Around these parts I am known as the Mithril Kid. I supply ornate mithril to adventurers from around the world.\n\n<Trenton whispers.>\n\nLittle do they know that I do not know the technique to fashion ornate mithril gloves. Shhhh! This will be our little secret.\n\nTeach me the technique to create ornate mithril gloves, $N, and in exchange, I will show you the resultant of the culmination of my training under Galvan: the ornate mithril breastplate.", objectives = "Bring two Heavy Mithril Breastplates and one Ornate Mithril Gloves to Trenton Lighthammer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2781] = { title = "WANTED: Caliph Scorpidsting", description = "WANTED: Caliph Scorpidsting!\n\nThe Gadgetzan Water Company of Gadgetzan, Tanaris will pay a high bounty for the head of Caliph Scorpidsting, leader of the Wastewander outlaws.  His crimes include:\n\n1.  Murdering Gadgetzan Water Co. employees!\n2.Stealing Gadgetzan Water Co. resources!\n3.Seizing Gadgetzan Water Co. property!\n\nBring proof of Caliph Scorpidsting's demise to Chief Engineer Bilgewhizzle for an immediate reward!", objectives = "Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2782] = { title = "Rin'ji's Secret", description = "The tablet is covered with Witherbark troll markings. Rin'ji's secret truly is a mystery... \n\nIt's possible that you might have something quite valuable on your hands here. On the other hand, quite the opposite is also possible. A Witherbark troll in distress would probably do anything to find his way out of trouble...", objectives = "Oran Snakewrithe, a well known scholar on matters concerning the Witherbark trolls, may be able to decipher the tablet. She is known to reside within the Magic Quarter of the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2783] = { title = "Petty Squabbles", description = "We fight the wrong enemy, $N.\n\nThe true power in these lands continues to grow in strength and number while we squabble over scorched earth with orcs.\n\nDo we continue to fight a war in these lands against the Horde, only to be routed one day by the armies of the Burning Legion? It is futile.\n\nPut your differences aside, $N, speak with the fallen hero of the Horde. He knows the truth behind the Blasted Lands.", objectives = "Speak with the Fallen Hero of the Horde at the border of the Blasted Lands and the swamp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2784] = { title = "Fall From Grace", description = "Hear my story, $r.", objectives = "Listen to the Fallen Hero of the Horde tell his story.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2801] = { title = "A Tale of Sorrow", description = "Before we may continue, you must hear my story.", objectives = "Listen to the Fallen Hero of the Horde tell his story.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2821] = { title = "The Mark of Quality", description = "My philosophy on leatherworking is that the work must be the best quality possible - no compromises.  Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!\n\nIn my latest pursuit of high-quality materials, I have run across thick yeti hides.  The Yeti are native to Feralas, with many found in Feral Scar Vale.  I want some, and I'll give you a choice of one of my leather goods for a stack of ten.  If that sounds fair to you, then we're in business.", objectives = "Bring 10 Thick Yeti Hides to Pratt McGrubben in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2822] = { title = "The Mark of Quality", description = "I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!\n\nIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found west of here in Feral Scar Vale.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!", objectives = "Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2841] = { title = "Rig Wars", description = "Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined. I need the blueprints, $N!\n\nUnfortunately, the plans are locked away in a safe near Mekgineer Thermaplugg. To make matters worse, the combination to the safe is only known by Mekgineer Thermaplugg.\n\nDo whatever you have to do to get that combination, $N. Then crack open that safe and bring back those blueprints!", objectives = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2842] = { title = "Chief Engineer Scooty", description = "As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.\n\nIt's finally ready for passengers to board, $N. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.\n\nOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!", objectives = "Speak with Scooty in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2843] = { title = "Gnomer-gooooone!", description = "As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.\n\nYou may experience some unusual side effects, but none of those should be permanent... anymore.\n\nI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!\n\nNow to calibrate the transponder to your size and weight.", objectives = "Wait for Scooty to calibrate the Goblin Transponder.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2844] = { title = "The Giant Guardian", description = "I am no good, $N. I was 'spose to be watchin' over my little friend, Shay, and somehow, she got away from me. I'm not all that sure what happened, really, but last time I saw her, we was walkin' through the ruins just north of here.\n\nEverythin' was goin' fine, but then I turned around, and... she was gone.\n\nNow I jus can't quite figure out what I should do here. Got any ideas, $N? I'm awful worried.\n\nHey, how 'bout you go look fer Shay? Yer legs can travel much faster 'n mine.", objectives = "Locate the lost night elf girl.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2845] = { title = "Wandering Shay", description = "Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then. There are just so many things to see, and I get so distracted.\n\nThere is one thing that will always work to get my attention, though.\n\nInside this chest, you'll find a bell that is very precious to me. I just love the sound of it. You have my word, if I wander off, all you have to do is ring it and I'll come running back.", objectives = "Pick up Shay's Bell from the chest.\n\nEscort Shay Leafrunner to Rockbiter's camp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2846] = { title = "Tiara of the Deep", description = "Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep.  And not only was it pretty--it held great power for those with the knowledge to use it.\n\nSo when word of the tiara reached the Hydromancer Velratha, she had to have it.  She sent agents to my home and they stole it while I was away.  The thieves!\n\nI want my tiara back!  Go to Zul'Farrak, the troll city in Tanaris, find Velratha and wrench the tiara from her.  Return it to me and you'll earn my favor.", objectives = "Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2847] = { title = "Wild Leather Armor", description = "$n, you're becoming quite skilled as a leatherworker!  I know some patterns you might be interested in... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  The armor made using it is second to none for people of your skill, guaranteed.\n\nI'll teach this to you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.", objectives = "Bring 10 Thick Leather to Pratt McGrubben in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2848] = { title = "Wild Leather Shoulders", description = "Wild Leather shoulders support the wearer's frame extremely well, offering top notch protection of the upper arms and the shoulders themselves.  As with all Wild Leather armor, a potent but random benefit is applied to the item as the wildvine is stitched in.\n\nFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.", objectives = "Bring 6 Thick Armor Kits and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2849] = { title = "Wild Leather Vest", description = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest blends with the wildvine to produce a product that offers maximum protection of the torso while allowing for the potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  It's a tall order, but one you should have little difficulty in filling for me.", objectives = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2850] = { title = "Wild Leather Helmet", description = "A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random enhancement to the frame of the helm.  Leather wearers will definitely want this piece!\n\nFor this pattern, I will need two Nightscape tunics, two Nightscape headbands, and a wildvine.  Complete this order and the pattern will be yours!", objectives = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2851] = { title = "Wild Leather Boots", description = "You've learned quite a bit now, $n; still, there is more for you to learn.  Next are Wild Leather boots, the cornerstone of any set.\n\nThese boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.\n\nFor this pattern, I need an order of two Nightscape pants and two Nightscape boots filled.  I also will require two wildvines... not just one.  When you have all this, let me know.", objectives = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2852] = { title = "Wild Leather Leggings", description = "With the basics down, you are ready to master more complex fare, $n.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.\n\nFor this pattern, I need an order of two Turtle Scale helms, two Turtle Scale bracers, and two wildvines filled.", objectives = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2853] = { title = "Master of the Wild Leather", description = "Well $n, you are the definition of diligence.  There is one pattern left for Wild Leather armor; you've mastered the others.  I won't require you to toil needlessly for the pattern.  You've earned it outright, and then some... but I cannot give it to you myself.  My teacher, the one who brought me into the craft, is the one who must reward you.\n\nTake this letter to Telonis; he teaches leatherworking in Darnassus.  Show him the letter, and let him acknowledge you as an equal, as I do.", objectives = "Give Pratt's Letter to Telonis, the master leatherworker of Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2854] = { title = "Wild Leather Armor", description = "$n, your skill as a leatherworker precedes you.  I possess leatherworking lore you would be wise to acquire... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  Armor made using it is second to none for a crafter of your skill, guaranteed.\n\nI'll teach you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.", objectives = "Bring 10 Thick Leather to Jangdor Swiftstrider in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2855] = { title = "Wild Leather Shoulders", description = "Wild Leather shoulders support a wearer's frame extremely well, offering superior protection of the upper arms as well as the shoulders.  As with all Wild Leather armor, a random yet very potent enhancement is imbued within the item as the wildvine is stitched in.\n\nFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.", objectives = "Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2856] = { title = "Wild Leather Vest", description = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest and the wildvine weave within it produces a product that offers maximum protection of the torso while allowing for potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  This is not an easy lesson, but it is one you certainly have the skill to complete.", objectives = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2857] = { title = "Wild Leather Helmet", description = "A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random magic imbuement to the helm's frame.  Leather wearers will definitely want this piece!\n\nFor this pattern, I will need two Nightscape tunics, 2 Nightscape headbands, and a wildvine.  Complete this lesson and the pattern will be yours!", objectives = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2858] = { title = "Wild Leather Boots", description = "Your knowledge of Wild Leather armor grows, $n; still, there is more for you to learn.\n\nWild Leather boots are the cornerstone of any set.  Such boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.\n\nFor this pattern, I need two Nightscape pants and two Nightscape boots crafted.  I also will require two wildvines... not just one.  When you have these items, we will proceed.", objectives = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2859] = { title = "Wild Leather Leggings", description = "You are ready to master more complex lessons, $n.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.\n\nFor you to gain this pattern, I need two Turtle Scale helms, two Turtle Scale bracers, and two wildvines.", objectives = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2860] = { title = "Master of the Wild Leather", description = "$n, you have learned all I am able to teach you.  There is, however, one remaining pattern for Wild Leather armor.  I will not require you to toil needlessly for this; you've earned it outright, and then some.  This pattern, however, is one that I cannot freely share with you.\n\nMy teacher, the one who brought me into the craft, is the one who must reward you.  Take this note to Una; she teaches leatherworking in Thunder Bluff.  Show her the letter, and let her acknowledge you as an equal, as I do.", objectives = "Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2861] = { title = "Tabetha's Task", description = "Rumor is that Tabetha, a mage colleague who lives deep in Dustwallow Marsh, has a bone to pick with a certain sand troll in Zul'Farrak.  If you speak with Tabetha she can tell you more.\n\nAnd bring some friends with you, $N.  If Tabetha has you go to Zul'Farrak then you're not going to want to go alone.\n\nYou will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruin.", objectives = "Speak with Tabetha in Dustwallow Marsh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2862] = { title = "War on the Woodpaw", description = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.\n\nThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.\n\nGo!", objectives = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2863] = { title = "Alpha Strike", description = "The plan is for various leaders of the gnolls - Alphas as they call themselves - to be taken down within rapid succession.  If we're able to execute this sort of swift and precise devastation against them, it would cause chaos in their ranks.  Perhaps it would also drive a message through their thick flea-bitten heads that we can and will destroy them!\n\nI want you to be the messenger of my will; eliminate five of their Alphas within one hour for this to work $N, or we'll remain at this impasse!", objectives = "Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2864] = { title = "Tran'rek", description = "My cousin Tran'rek is in a tight spot.  He promised me a load of scarab shells weeks ago and he hasn't delivered.  He's my cousin, so I'd hate to have to send someone to Gadgetzan to break something on him.\n\nCan you speak to Tran'rek for me?  Let him know he needs to get that delivery together before I do something rash?\n\nGadgetzan is in northern Tanaris, in Kalimdor.", objectives = "Speak with Tran'rek in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2865] = { title = "Scarab Shells", description = "The scarabs of Tanaris have very hard shells!  Hard enough to use as a building material for lots of things.  So many things!\n\nIn fact, those shells are so useful... the scarabs were hunted all to near extinction!\n\nI know where there are more scarabs, and if you promise to bring me their shells then I'll tell you where they are.  Promise?\n\nOk, the scarabs have a colony in Zul'Farrak.  I guess the trolls don't hunt them for their shells.\n\nBut you can!  Go to Zul'Farrak and get me uncracked shells!", objectives = "Bring 9 Uncracked Scarab Shells to Tran'rek in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2866] = { title = "The Ruins of Solarsal ", description = "To our south are the Ruins of Solarsal; this is an area that far pre-dates modern times.  We explored the ruins initially and found nothing of note; as such, we left it in peace.\n\nVery recently, the Hatecrest naga have occupied these ruins in alarming numbers.  At first, we considered it as the precursor for an attack.  Though that threat is still possible, we believe there might be something else going on.\n\nGo there, explore the ruins, and look for anything that stands out to you. Good luck, $n.", objectives = "Explore the Ruins of Solarsal and investigate the presence of the naga there.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2867] = { title = "Return to Feathermoon Stronghold", description = "With the discovery of the strange gazebo in the heart of the Ruins of Solarsal, the time has come to return to Feathermoon Stronghold and report to General Shandris Feathermoon what has been discovered here.", objectives = "Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2869] = { title = "Against the Hatecrest", description = "The best course of action at this point is to assume that, regardless of what the naga are up to, they will eventually move to secure the island for their own.  We need to take aggressive steps to counter that threat before it is too late.\n\nBring me ten Hatecrest Scales that are in good condition; it should be obvious to you how to acquire them.  You'll cut your teeth on the naga for the first time, and we'll have a weakened naga presence on Sardor Isle - both are prospects that play to our advantage.", objectives = "Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2870] = { title = "Against Lord Shalzaru", description = "$n, new scouting reports have given us a good idea on the naga chain of command.  Royalty is present amongst their rank and file, and they're the ones calling all the shots.\n\nSpecifically, we've identified one of the crueler royals as Lord Shalzaru.  Scouts report that he himself has uncovered an odd relic during a recent naga excavation in a cave south of the main ruins, across the water on the Isle of Dread.\n\nPut a stop to it by putting a stop to him, and bring me his relic so we can study it.", objectives = "Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2871] = { title = "Delivering the Relic", description = "If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it.  She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere.  I couldn't make heads or tails of this device even if there was a wager involved.  My wife though, if anyone can figure out what this thing is, she could... and we need to know!\n\nShe's just around the bend, no doubt studying.  Thanks, $n.", objectives = "Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2872] = { title = "Stoley's Debt", description = "My old buddy Stoley owes me a very special bottle of rum.  He tends the bar at Steamwheedle Port in Tanaris, Kalimdor,  and he promised me that the rum there is stronger than anything we can find in Booty Bay.  He's so confident that he says if I try that rum and don't agree with him, then he'll double the money he owes me!\n\nWell, I think he's not as confident as he was when last we spoke, and now he's afraid to give me that rum.  But I don't back down from wagers, so why don't you talk to him for me...", objectives = "Speak with Stoley in Steamwheedle Port.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2873] = { title = "Stoley's Shipment", description = "I owe \"Sea Wolf\" MacKinley in Booty Bay some rum, to settle a bet, but I'm all out of rum!  Captain Cuergo stole my last shipment, and he has it stowed in that walled pirate town to the south.\n\nIf you can find my shipment of rum and return it to me, then I can prove to MacKinley that Kalimdor's booze beats the dirt out of Booty Bay!", objectives = "Bring Stoley's Shipment to Stoley in Steamwheedle Port.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2874] = { title = "Deliver to MacKinley", description = "Thanks again for your help, $N.  Here's a bottle of Steamwheedle bilge rum.  Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze.", objectives = "Bring Stoley's Bottle to \"Sea Wolf\" MacKinley in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2875] = { title = "WANTED: Andre Firebeard", description = "The vile pirate Andre Firebeard is wanted for crimes against Steamwheedle and Gadgetzan.\n\nBy decree of governing counsel, any who read this are hereby authorized to use lethal force during the apprehension of Andre and his abettors.\n\nBy further decree, should Andre be deceased, or otherwise indisposed, during the time of his hearing, his head may act as proxy, and deliverance of such head to Security Chief Bilgewhizzle constitutes a binding, and tenderable, contract.", objectives = "Bring Andre's Head to Security Chief Bilgewhizzle in Steamwheedle Port.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2876] = { title = "Ship Schedules", description = "This scroll contains the schedules of shipments between Steamwheedle Port and Booty Bay. Both past and future shipments are included, along with ship names, with large 'X's next to some ships' journeys, and annotations like \"GREAT LOOT\" and \"HARD FIGHT\" next to others.\n\nSomeone at Steamwheedle Port would want to see this document.", objectives = "Report the Ship Schedules to an authority in Steamwheedle Port.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2877] = { title = "Skulk Rock Clean-up", description = "We Wildhammers remember the past, more than our brothers in Ironforge.  If you want to make friends here, then you get your hands dirty for us!\n\nThe Horde abandoned their positions in the Hinterlands around Skulk Rock; it's now overrun with nasty sludges and oozes.  We've got plans on that area, but first we need a clean-up crew to make a hole for us.\n\nThat's where you come in, Sunshine!  Head down there and take out ten green sludges and ten jade oozes, then report back to me here.  Move out!", objectives = "Kill 10 Green Sludges and 10 Jade Oozes, and then report back to Fraggar Thundermantle in Aerie Peak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2878] = { title = "Corrupted Songflower", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2879] = { title = "The Stave of Equinex", description = "This stave might be the Stave of Equinex! The Stave of Equinex is actually a key, used to unlock the Equinex Monolith in the Ruins of Ravenwind, on the mainland west of the Dream Bough.\n\nFind the four flames that still burn in those ruins: Samha, Imbel, Byltan, and Lahassa. Retrieve their essence and then while standing by the Equinex Monolith, use the essences to energize the stave. If this is truly is the Stave of Equinex, you will be able to unlock the Monolith and gather a sacred artifact from it.", objectives = "Energize Troyas' Stave and find the Equinex Monolith.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2880] = { title = "Troll Necklace Bounty", description = "Get this straight, $r - we are NOT part of the Alliance!  The Wildhammers are independent, relying on deeds and actions to prove one's worth, rather than the blather of those who use jibber-jabber to bolster their do-nothing attitudes!\n\nIf you're looking for friends here, then prove your worth to us first!  The foul trolls that choke the hillsides of the Hinterlands sometimes carry tribal necklaces.  Bring five of them to me, and we'll mark it down as a step in the right direction for you.", objectives = "Bring 5 Troll Tribal Necklaces to Fraggar Thundermantle in Aerie Peak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2881] = { title = "Troll Necklace Bounty", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2882] = { title = "Cuergo's Gold", description = "This map shows a stretch of beach with a southern face.  Below the map are words, elegantly written...\n\n\nSouth of Wheedle\nSouth of home\nFind a mast and flag and bones\nDig you there, if you be bold\nDig and claim Cuergo's gold!\nA key you'll need and a key you'll see\nThe men you face take blood as fee.", objectives = "Find Cuergo's gold!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2902] = { title = "Woodpaw Investigation", description = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity.  If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.\n\nI want you to head back to the Woodpaw and find anything that might resemble their battle plans.  They have to have something; their attacks have been too coordinated to be done without them.  Find them, and return to me when you have them.", objectives = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2903] = { title = "The Battle Plans", description = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.", objectives = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2904] = { title = "A Fine Mess", description = "<Kernobee groans.> Wha.. What happened?\n\nThe last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs.\n\nGet me out of here, $N!\n\nHere's the plan: Lead me to the exit; if we make it out alive, you go to Booty Bay and let Scooty know that I went to Ratchet to warn Tinkerwiz of the dark iron's involvement in the making of that super rig.\n\nLet's get going!", objectives = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2922] = { title = "Save Techbot's Brain!", description = "When our beloved city Gnomeregan fell, a rogue spark must have jolted my poor creation, Techbot.  It once aided me and my associates with its countless gizmos and limitless store of information, but its positronic brain has polarized.  Now it's negatronic... and Techbot's behaviors are reversed.  It roams Gnomeregan in a frenzy!\n\nBut perhaps it can be salvaged.  Perhaps, if you can retrieve Techbot's memory core and bring it to me, I can discover the cause of the polarization and fix my poor Techbot.\n\n", objectives = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2923] = { title = "Tinkmaster Overspark", description = "Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot.  I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.\n\nVery sad.  But with luck perhaps he can be fixed!\n\nSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge.  He would welcome your help.", objectives = "Speak with Tinkmaster Overspark in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2924] = { title = "Essential Artificials", description = "A nigh-universal mechanical component--the essential artificial--was of great use to the tinkers and smiths of Gnomeregan.  But during the frantic exodus from our city, no one remembered to take any of these devices with them!  And I need a large supply of them for work I will soon undertake.\n\nPlease, go into Gnomeregan and get me some essential artificials.  You'll find them in the deeper areas of our city, held in containers called artificial extrapolators.\n\nThank you, $N, and please hurry!", objectives = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2925] = { title = "Klockmort's Essentials", description = "A gnome friend, Klockmort Spannerspan, sent word to me from Ironforge.  He tells me he needs help on a dangerous, but essential, mission into Gnomeregan, the once great gnome city now contaminated and filled with mad gnomes and their devices.\n\nI must stay here, but my heart aches to help my friend.  If you can go in my stead, then I would be much indebted to you.\n\nYou may find Klockmort in Tinkertown, in Ironforge.", objectives = "Speak with Klockmort Spannerspan in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2926] = { title = "Gnogaine", description = "Since the accident, all Gnoarn thinks about or talks about is cleansing Gnomeregan of the trogg infestation and finding a cure for the sickness that plagues it, $N.\n\nLuckily, Razzle and I are close to some kind of cure - either that or the recipe for a really powerful rum. We won't know until we test! Naturally, in order to test our theory, we're going to need a few things; namely, fallout from the irradiated troggs in Gnomeregan. Fill up this phial with the green glow and bring it back!", objectives = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2927] = { title = "The Day After", description = "You don't think I was always bald, do you? No $g sir:ma'am;! It was the radiation leak in Gnomeregan that caused this tragic hair loss. Before that day, I had the only gnomefro in all of Azeroth.\n\n<Gnoarn shakes his fist in the air.>\n\nDamn those damned dirty troggs - damn them all!!\n\nPerhaps it's not too late, $N. We may still be able to save it - the city I mean! Speak to Ozzie Togglevolt in Kharanos. He and his partner Razzle are working on a solution.", objectives = "Speak with Ozzie Togglevolt in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2928] = { title = "Gyrodrillmatic Excavationators", description = "It's terrible, $N. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh.\n\nWhat we need are spare parts, $N. What better place to get the spare parts for our vehicles than Gnomeregan? I hear that bots and mechs roam around that place like cattle on an open range.\n\nWhat I need you to do is go to Gnomeregan and tear apart those robots. Bring me back their robot guts. Two dozen should be sufficient.", objectives = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2929] = { title = "The Grand Betrayal", description = "I trusted Thermaplugg, $r. Never did I expect that he would betray me and the entire gnomish people. And for what? Power? Wealth? All things that he would have had in time. Now we have been displaced from our home and that madman is in charge. The king of nothing....\n\nWe will retake Gnomeregan, $N. We will not stop until the city is back in our control. If you wish to join in our fight, a simple task I ask of you: Kill the betrayer. Destroy Mekgineer Thermaplugg.", objectives = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2930] = { title = "Data Rescue", description = "When we fled Gnomeregan, we left so much data behind!  Vitally important data!\n\nI need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan.  You must access the terminal, but to do that you first need clearance... and to get that you must access lower security terminals-- models -A, -B and -C.  And to do THAT you need security punch cards, starting with white... and we left all the punch cards in the city.\n\nIt's a catastrophe!  Can you help?", objectives = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2931] = { title = "Castpipe's Task", description = "Master Mechanic Castpipe in Ironforge has need of adventurers!  He's organizing bands to reenter Gnomeregan on a data retrieval mission of top security and importance.\n\nCastpipe might not be a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences like I am, but he's still a smart gnome so if he thinks it's important, then by my calculations there's an eighty-four percent probability that it really is important!\n\nThose are good odds!", objectives = "Speak with Master Mechanic Castpipe in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2932] = { title = "Grim Message", description = "The Witherbark trolls were once allies to the Horde, but they betrayed Thrall... and that must be punished!\n\nHere, take my pike and go to the Hinterlands, far to the north.  You will find it northeast of Tarren Mill, a village held by our allies, the Forsaken.\n\nWhen you enter the Hinterlands, hunt Witherbark trolls.  Gather their skulls and drive my pike into the ground at one of their smaller villages, Hiri'watha or Zun'watha.\n\nShow them their vile actions are of consequence!", objectives = "Gather Witherbark Skulls and place on Nimboya's Pike.  Place Nimboya's Laden Pike at one of the Witherbark Villages in the Hinterlands, then return to Nimboya in Stranglethorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2933] = { title = "Venom Bottles", description = "These bottles hold a vile, green venom.\n\nConsidering the number of bottles in this village, the Witherbarks must deem it very important.  Perhaps an apothecary in nearby Tarren Mill would like a sample.", objectives = "Bring a Venom Bottle to an apothecary in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2934] = { title = "Undamaged Venom Sac", description = "I must have a fresh sample of the venom you brought me.  The spiders from which it was gathered must dwell in the Hinterlands -- hunt them until you find an undamaged venom sac and bring it to me.  You will find many spiders near the troll city of Shadra'Alor.\n\nDo not tarry, $N, for the venom sac must be fresh when you deliver it.", objectives = "Bring an Undamaged Venom Sac to Apothecary Lydon in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2935] = { title = "Consult Master Gadrin", description = "The venom from the broodguards wasn't as potent as the venom you brought originally.  It must have come from a different spider.\n\nI want a fresh sample of that venom.  To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village.  Travel to Durotar and speak with Gadrin.  With luck, he'll know where the Witherbarks get their venom.", objectives = "Speak with Master Gadrin in Sen'jin Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2936] = { title = "The Spider God", description = "The Witherbarks worship a spider god, and from her they collect their most potent venom.  So if you want the venom, then you must summon their god!\n\nTo do that, you must know her true name, and that name is on a tablet buried in Tanaris, in the troll city of Zul'Farrak, in a tomb guarded by Theka the Martyr.\n\nDefeat Theka and find and read his tablet to discover the spider god's name.  When you know it, return to me.", objectives = "Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2937] = { title = "Summoning Shadra", description = "Take his parchment, and read it at the altar of Shadra'Alor, deep within the witherbark realm in the Hinterlands.  This will summon Shadra the spider god.", objectives = "Defeat Shadra at the altar of Shadra'Alor, then bring her venom to Apothecary Lydon in Tarren Mill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2938] = { title = "Venom to the Undercity", description = "The venom you gathered from the Witherbark's spider god is quite a find!  I've been able to kill nearly two dozen rabbits with just a drop of the stuff.  Granted, some of those rabbits were very young and small enough to fit in the palm of one's hand so I'm certain their resistance to toxins was low, but it can't be denied that this poison is powerful!\n\nI'd like a sample sent to my superior, Apothecary Faranell in the Apothecarium of the Undercity.  I am positive he would want to test this himself.", objectives = "Bring Faranell's Parcel to Master Apothecary Faranell in the Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2939] = { title = "In Search of Knowledge", description = "While the ruins of Feralas can be quite dangerous, they have much to tell of what has happened here.\n\nSearching through the rubble to the south a few days ago, I discovered what appears to be a normal stave. However, I just can't shake the feeling that there is something more to it. Angelas and I have been poring over our books here, but we can't find a thing about it.\n\nI have a colleague in Darnassus that may be able to tell us what this is, $N. Why don't you go talk to her and see if she can help us?", objectives = "Talk to Daryn Lightwind in Rut'theran Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2940] = { title = "Feralas: A History", description = "This book looks as if no one has opened it for quite a long time. Its covers are quite worn, and its pages yellowed, but after examining it, you notice that it might be just what Troyas is looking for.\n\nYou pick it up, but realize you should probably ask before borrowing it.", objectives = "Ask Daryn Lightwind if you may borrow her book.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2941] = { title = "The Borrower", description = "I have studied many subjects in my time, and my latest fascination is with the snapjaw that occupy the beach in the Hinterlands. There's one in particular I'd like to see, a giant snapjaw named Gammerita. I'd like to go myself, but my research keeps me here. I think a picture of her would be the next best thing.\n\nTake this letter to Curgle Cranklehop in Tanaris. She has created an invention for me that can capture a picture. She called it a \"snapshot,\" I think...", objectives = "Take the letter to Curgle Cranklehop in Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2942] = { title = "The Morrow Stone", description = "The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade.", objectives = "Return the Sparkling Stone and the Stave of Equinex to Troyas Moonbreeze in Feathermoon Stronghold. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2943] = { title = "Return to Troyas", description = "Here it is, $N. Please, take care of my book.\n\nNow, hurry along. I'm sure Troyas is eager for your return.", objectives = "Deliver the book to Troyas Moonbreeze in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2944] = { title = "The Super Snapper FX", description = "Have the first look at my new invention, $N. All you need to do is target whatever it is you'd like to take a picture of, and push the button.\n\nWhat was that creature from the Hinterlands that you mentioned? Gammerita? Well, good luck finding her. I'm sure Daryn will be quite pleased with the snapshot you return to her.\n\nIn any case, here's the Super Snapper. Have fun!", objectives = "Use the Super Snapper FX to take a snapshot of Gammerita, then return to Daryn Lightwind in Rut'theran Village.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2945] = { title = "Grime-Encrusted Ring", description = "You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves.  It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible.  You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue.\n\nIf you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it.", objectives = "Figure out a way to remove the grime from the Grime-Encrusted Ring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2946] = { title = "Seeing What Happens", description = "We want you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.\n\nThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.\n\nWhen you've found out what happens, return to Ironforge.  We'll have a lot to analyze when you're done!", objectives = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2947] = { title = "Return of the Ring", description = "Opening the box produced by the Sparklematic 5200 reveals what you had suspected - a shiny ring!  Wearing the ring, you feel magic power surge through you body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Ironforge.  Next to that, three small initials are engraved: \"TdK\".  This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or return it to this person.  Decisions, decisions...", objectives = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2948] = { title = "Gnome Improvement", description = "Listen $n, that ring is yours, sure... but I can make you a better one!  That design, like I said, is really simple.  I am a lot more skilled now, and for the mere fee of thirty silver coins I'll spruce it up for you!  Well, a little more than thirty, actually...\n\nI'm in a tight spot right now; all my material stock is all dried up.  If you bring me a bar of silver and a moss agate, I'll add a silver and agate lattice to the ring that will give it a little more pizzazz!\n\nTrust me!", objectives = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2949] = { title = "Return of the Ring", description = "Opening the box produced by the Sparklematic 5200 reveals a shiny ring!  Donning the ring, you feel magic power surge through your body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar.  Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\"\n\nThis may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or find \"NOG\" - decisions, decisions...", objectives = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2950] = { title = "Nogg's Ring Redo", description = "No, no, no - I'm not all of the sudden saying that the ring is mine.  I normally don't do this, but your information about the Dark Irons was very useful.  I'll improve your ring for you, better than whomever made this simple little thing could have ever done.  Probably some gnome...\n\nIf you bring me a bar of silver, a moss agate, and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it.  Interested?", objectives = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2951] = { title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", objectives = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2952] = { title = "The Sparklematic 5200!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2953] = { title = "More Sparklematic Action", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2954] = { title = "The Stone Watcher", description = "\"Salutations - I am a guardian of entry.  Unless you have the Plates of Uldum already integrated with your disc set, I will not allow for entry into the Uldum compound.\"\n\nThe appearance of the Stone Watcher of Norgannon must be the reaction that was hoped for in sending you out to the Tanaris desert with the platinum discs.  As instructed, you will need to find out what the story behind the Stone Watcher is before continuing on.", objectives = "Learn the purpose of the Stone Watcher of Norgannon, and then interact with the Uldum Pedestal in the Tanaris desert.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2962] = { title = "The Only Cure is More Green Glow", description = "Not only was your sample insufficient in quantity, it was also impure.\n\nWhat we require is more green glow. The troggs are obviously not irradiated sufficiently to fulfill our needs. You will have to go into Gnomeregan and bring back some radioactive fallout, straight from the tap. I am speaking of the irradiated slimes, lurkers and horrors. Be warned, the containment of this type of fallout is difficult. You may need to make several attempts with the phial until a suitable sampling is recovered.", objectives = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.\n\nOzzie will also require your Heavy Leaden Collection Phial when the task is complete.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2963] = { title = "Portents of Uldum", description = "Greetings once again, $n!  Your discovery inside Uldaman has set the Explorers' League abuzz with excitement.  The League has been working to unlock the secrets of the miniature platinum discs you found.  Your fortuitous arrival here in the Hall allows me to share with you that we are quite possibly on to something!\n\nHistorian Karnik has uncovered some important clues as to the true origins of the Valley of the Watchers in the Tanaris desert.  He would like to speak with you as soon as possible!", objectives = "Speak with Historian Karnik in the Hall of Explorers within Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2964] = { title = "A Future Task", description = "Well $n... we seem to be at a temporary dead end here.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We'll need to do quite a bit of research on this to come up with a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to head out and recover them.\n\nThe High Explorer needs to be informed on this, $n; no doubt, he also wants to thank you personally for once again aiding the League.", objectives = "Speak with High Explorer Magellas in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2965] = { title = "Portents of Uldum", description = "Ah, $n, it is fortuitous that you have come to me again.  Your revelations at the Uldaman dig site have certainly given us sages much discuss.  I was doing just that with one of the druids, Nara Wildmane, when it dawned on me that her past adventuring experiences may have some great importance as to the next step we need to take.\n\nI would like for you to speak with her concerning her travels to the Valley of the Watchers in the Tanaris desert.  She waits for you on the Elder Rise.", objectives = "Speak with Nara Wildmane on the Elder Rise in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2966] = { title = "Seeing What Happens", description = "Sage Truthseeker and I would like you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.\n\nThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.\n\nLearn what you can, then return to me. We will have much to discuss.", objectives = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2967] = { title = "Return to Thunder Bluff", description = "You access the pedestal again; the platinum discs suddenly appear once more in your backpack.\n\nWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Thunder Bluff and inform the Nara Wildmane of your discovery.", objectives = "Speak with Nara Wildmane in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2968] = { title = "A Future Task", description = "Well $n... we seem to be at an unfortunate impasse.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We will research this, and then devise a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to rejoin our efforts to discover the truth.\n\nSage Truthseeker needs to be informed on this, $n; no doubt, he also wants to thank you personally for once again heeding the call.", objectives = "Speak with Sage Truthseeker in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2969] = { title = "Freedom for All Creatures", description = "The filthy Grimtotem clan are capturing faerie dragons, $N. Jer'kai and I have no idea what they plan on doing with them, but they're obviously up to no good.\n\nWe're not powerful enough to fight our way into the camp and free the captured dragons, but perhaps with your help...\n\nIf you're willing, and you have some strong friends, release the creatures from their cage with this key and make sure they escape with their lives. I'll be by your side the entire time. Jer'kai will remain here.", objectives = "Using the Bamboo Cage Key, free the Sprite Darters from the pen in the Grimtotem camp. At least 6 Sprite Darters and Kindal Moonweaver must survive.\n\nYou have 6 minutes before Kindal decides it is time to retreat and you fail the quest.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2970] = { title = "Doling Justice", description = "As she's already told you, Kindal and I will now take the fight to the Grimtotem. Together, we should still be able to pick off some of the tauren without much threat to ourselves, but we'd love some help if you're willing and able.\n\nYou've seen the camp below us, but there are more to the east. Using your own tactics, deal as much damage to the tauren as you can. We can all meet back here after they've felt the sting of Kindal's arrows and your own weapons.", objectives = "Kill 12 Grimtotem Naturalists, 10 Grimtotem Raiders, and 6 Grimtotem Shamans before returning to Jer'kai Moonweaver in Feralas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2972] = { title = "Doling Justice", description = "Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring. If you ever find yourself in the boughs of Teldrassil, go to the Temple of the Moon in the heart of Darnassus. There you will find my High Priestess Tyrande Whisperwind. The ring will let her know that we are well and give credit to your story.\n\nWe both thank you, $N.", objectives = "Take Jer'kai's Signet Ring to High Priestess Tyrande Whisperwind in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2973] = { title = "A New Cloak's Sheen", description = "Well met, $c. I've traveled with my companions down to the Feralas on a mission for our Orgrimmar masters.\n\nMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with gorgeous wings I want are west of Camp Mojache.", objectives = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2974] = { title = "A Grim Discovery", description = "What!? You came across tauren in the area? You're joking! What did they look like!?\n\nThe Grimtotem clan! You found some of them? Belgrom, one of our masters, has an interest in their kind... he's even put a bounty on them.\n\nYou have to go back, $c. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.", objectives = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2975] = { title = "The Ogres of Feralas", description = "The effects of the Gordunni Ogre tribe can hardly go unnoticed in this area. Look around, $N; their very presence scars this land. We must push them back before they expand even further into Feralas.\n\nFollow the river north, and you will find their outpost. Decrease their numbers, $N. We must show them that their kind is not wanted here.", objectives = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2976] = { title = "A Grim Discovery", description = "What?!\n\nAh, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it?\n\nYou did the work, so I suppose it is only right you reap the greatest reward from it. Take the horns, I'll have them put in a crate for you. Find Belgrom Rockmaul in the Valley of Honor, he'll want to know what you saw and he'll reward you for your hard work.\n\nBe well, $c, and thank you again for everything you've done.", objectives = "Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2977] = { title = "Return to Ironforge", description = "You access the pedestal again; the platinum discs suddenly appear once more in your backpack.\n\nWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Ironforge and inform the Explorers' League of your discovery.", objectives = "Speak with Historian Karnik in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2978] = { title = "The Gordunni Scroll", description = "Picking up the soiled scroll, you notice that it seems to be depicting some sort of meeting or ceremony. Rok Orhan would be interested in this scroll, and what it might mean to the Gordunni.", objectives = "Bring the Gordunni Scroll to Rok Orhan in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2979] = { title = "Dark Ceremony", description = "These seem to be plans for some sort of dark ceremony, $N. From what I can make out, this ritual is conducted by the Gordunni mage-lords.\n\nFind one of these mage-lords, and from him, gather an orb.\n\nThe orb of a mage contains great power, and will help us discover more about this ceremony and the magic that the Gordunni wield.", objectives = "Rok Orhan in Camp Mojache wants you to find a Gordunni Orb.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2980] = { title = "The Ogres of Feralas", description = "Now that you have proven that you are a true fighter, I trust that you possess the courage to continue with the task at hand.\n\nTravel to the High Wilderness, southwest of here. There lie some abandoned and destroyed structures, on land that once belonged to the night elves. Look for these ruins, and when you see the withered trees and desecrated terrain, you will find the Gordunni. Push them back.\n\nThese ogres are much stronger than the ones you faced previously, $N. Be aware.", objectives = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2981] = { title = "A Threat in Feralas", description = "Feralas is an ideal location for an accomplished $c to prove $Ghimself:herself;. A tribe of ogres called the Gordunni are the dominant military force there, and their numbers are growing. They must be stopped before they threaten our presence in Feralas.\n\nA warrior I know of named Rok Orhan resides at Camp Mojache in Feralas; go to her. She will tell you more of the situation when you arrive.", objectives = "Belgrom Rockmaul wants you to speak with Rok Orhan in Camp Mojache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2982] = { title = "The High Wilderness", description = "Although it is dangerous, Troyas and I have been investigating the ruins that cover the forests of Feralas.\n\nLately, though, Troyas has been going on his own to the High Wilderness, and I really worry about him. The Gordunni Ogres have taken over that area, and they don't take kindly to anyone that enters their territory.\n\nI was hoping you might be willing to travel to the ruins to the southeast and clear out some of the ogres. Make it a little safer for my Troyas, and I will be extremely grateful.", objectives = "Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2983] = { title = "Call of Fire", description = "It's been some time since you were tested last, $N. You've been patient thus far in your studies, but it's time for you to learn about greater powers... it's time you learn real power. The element of fire is yours if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the blasted night elf lands, you've gone way too far.", objectives = "Find Kranal Fiss in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2984] = { title = "Call of Fire", description = "Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.", objectives = "Find Kranal Fiss in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[2985] = { title = "Call of Water", description = "You look ready for your next test, $N. You've been patient in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, $N.", objectives = "Find Islen Waterseer in the Barrens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
